<template><div class="portal-set-password"><div class="card"><h1>Configura tu contraseña</h1><p v-if="email">para <strong>{{email}}</strong></p><p v-else>Protege tu cuenta del portal</p><form v-if="valid" @submit.prevent="submit"><label>Nueva contraseña<input v-model="password" type="password" required minlength="8" placeholder="Mínimo 8 caracteres" autocomplete="new-password"></label><label>Confirmar contraseña<input v-model="confirm" type="password" required placeholder="Confirma la contraseña" autocomplete="new-password"></label><p v-if="error" class="error">{{error}}</p><button type="submit" :disabled="loading">{{loading?'Configurando...':'Configurar contraseña e iniciar sesión'}}</button></form><div v-else><p>{{invalidMsg}}</p></div></div></div></template><script>export default{data(){return{token:'',email:'',password:'',confirm:'',valid:false,error:'',loading:false,invalidMsg:''}},mounted(){this.token=new URLSearchParams(window.location.search).get('token')||'';if(!this.token){this.invalidMsg='El enlace de invitación no es válido o no está disponible.';return}this.validate()},methods:{async validate(){try{const{data}=await axios.get('/portal/validate-invite',{params:{token:this.token}});this.valid=data.valid;this.email=data.email||'';if(!this.valid)this.invalidMsg=data.message||'El enlace no es válido o ya venció.'}catch(_){this.invalidMsg='El enlace de invitación no es válido o ya venció.'}},async submit(){if(this.password!==this.confirm){this.error='Las contraseñas no coinciden';return}this.error='';this.loading=true;try{await axios.post('/portal/set-password',{token:this.token,password:this.password,password_confirmation:this.confirm});window.location.href='/portal/dashboard'}catch(e){const data=e?.response?.data||e;this.error=data?.message||'No se pudo configurar la contraseña'}finally{this.loading=false}}}}</script><style scoped>.portal-set-password{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:2rem;background:var(--pc-bg)}.card{width:100%;max-width:440px;background:var(--pc-surface);border:1px solid var(--pc-border);border-radius:18px;padding:2rem;box-shadow:var(--pc-shadow)}h1{margin-top:0}form,label{display:grid;gap:.6rem}form{gap:1rem}input{padding:.7rem;border:1px solid var(--pc-border-strong);border-radius:10px}button{padding:.7rem;background:var(--pc-primary);color:#fff;border:0;border-radius:10px}.error{color:var(--pc-danger)}</style>